<?php
require __DIR__.'/../bootstrap.php';
use App\Core\Database;use App\Core\SecureValue;
$pdo=Database::pdo();

function normalize_date_value(?string $v):?string{if($v===null||trim($v)===''||str_starts_with(trim($v),'0000-00-00'))return null;$v=trim($v);foreach(['Y-m-d H:i:s','Y-m-d','m/d/Y H:i:s','m/d/Y','n/j/Y'] as $fmt){$d=DateTime::createFromFormat($fmt,$v);if($d!==false)return $d->format(str_contains($fmt,'H:')?'Y-m-d H:i:s':'Y-m-d');}return null;}
function pick_client(array $r):?int{static $q=null;$q??=Database::pdo()->prepare('SELECT id FROM clients WHERE client_no=? OR (email IS NOT NULL AND email=? AND full_name=?) LIMIT 1');$q->execute([(string)($r['member_id']??''),$r['primary_email']??null,$r['member_name']??'']);$id=$q->fetchColumn(); return $id!==false?(int)$id:null;}
// Members -> clients
$src=$pdo->query('SELECT member_id,member_name,business_name,primary_email,phone,cell_phone,outstanding_balance FROM legacy_member_accounts');$ins=$pdo->prepare('INSERT INTO clients(tenant_id,client_no,full_name,first_name,last_name,email,phone,phone_cell,balance,unpaid_balance,created_at,updated_at) VALUES(1,?,?,?,?,?,?,?,?,?,NOW(),NOW()) ON DUPLICATE KEY UPDATE full_name=VALUES(full_name),email=VALUES(email),phone=VALUES(phone),phone_cell=VALUES(phone_cell),balance=VALUES(balance),unpaid_balance=VALUES(unpaid_balance),updated_at=NOW()');
foreach($src as $r){$name=trim($r['member_name']??'');$parts=preg_split('/\s+/',$name);$first=$parts[0]??'';$last=count($parts)>1?array_pop($parts):'';$ins->execute([$r['member_id'],$name,$first,$last,$r['primary_email']??null,$r['phone']??null,$r['cell_phone']??null,(float)($r['outstanding_balance']??0),(float)($r['outstanding_balance']??0)]);}
// Businesses -> linked to client_no
$insB=$pdo->prepare('INSERT INTO businesses(tenant_id,client_id,business_name,dba,ein_cipher,entity_type,president_name,registered_agent,street,city,state,zip,mail_street,mail_city,mail_state,mail_zip,business_start_date,incorporation_date,incorporation_state,year_end,tax_due_date,status,created_at,updated_at) SELECT 1,c.id,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,"active",NOW(),NOW() FROM clients c WHERE c.client_no=? LIMIT 1');
foreach($pdo->query('SELECT * FROM legacy_business_details') as $r){try{$insB->execute([$r['bus_name']??'Unknown Business',null,null,($r['entity_form_id']??null)!==null?'entity_form_id:'.$r['entity_form_id']:null,$r['president_name']??null,$r['res_person']??null,$r['bus_street']??null,$r['bus_city']??null,$r['bus_state']??null,$r['bus_zip']??null,$r['mail_street']??null,$r['mail_city']??null,$r['mail_state']??null,$r['mail_zip']??null,normalize_date_value($r['bus_start_date']??null),normalize_date_value($r['incorp_date']??null),$r['incorp_state']??null,$r['date_year_end']??null,normalize_date_value($r['tax_due_date']??null),$r['member_id']??null]);}catch(Throwable $e){file_put_contents(__DIR__.'/../storage/logs/normalize-errors.log',$e->getMessage()."\n",FILE_APPEND);}}
// Legacy invoices remain staging by default. This avoids creating false client mappings when member IDs are not unique.
echo "Normalized client/business profiles. Billing normalization remains available through reviewed import mappings.\n";
